insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('364a90b8-11a1-47e1-baad-cea033dad1cc', 'e3fa6b7d-ad8d-4f81-a97c-ffe0422ad106', $$f(x) = 1 + 3/(4x − 3); grafiek door de oorsprong O; figuur 1$$,
   $$wiskunde-b-havo-2021-i-gebroken-functie-en-wortelfunctie-context1.png$$,
   $$De functie f wordt gegeven door:
f(x) = 1 + 3/(4x − 3)
De grafiek van f gaat door de oorsprong O. Zie figuur 1.
figuur 1: de grafiek van f$$, 'inline'),
  ('493b68fa-65af-40a6-850c-4a17f1cb1d00', 'e3fa6b7d-ad8d-4f81-a97c-ffe0422ad106', $$f(x) = 4x/(4x − 3); g(x) = √x; gemeenschappelijke punten O en B; figuur 2$$,
   $$wiskunde-b-havo-2021-i-gebroken-functie-en-wortelfunctie-context2.png$$,
   $$Het functievoorschrift van f is ook anders te schrijven, namelijk:
f(x) = 4x/(4x − 3)
De functie g wordt gegeven door g(x) = √x.
De grafieken van f en g hebben twee punten gemeenschappelijk, O en B. Zie figuur 2.
figuur 2: de grafieken van f en g met het snijpunt B$$, 'inline'),
  ('552afe84-7418-4071-954d-d4e52960c020', 'e3fa6b7d-ad8d-4f81-a97c-ffe0422ad106', $$S snijpunt van de asymptoten van f; R snijpunt van g met de verticale asymptoot van f; figuur 3$$,
   $$wiskunde-b-havo-2021-i-gebroken-functie-en-wortelfunctie-context3.png$$,
   $$De grafiek van f heeft een horizontale en een verticale asymptoot. Het punt S is het snijpunt van deze twee asymptoten.
De grafiek van g snijdt de verticale asymptoot van f in het punt R. Zie figuur 3, waarin de asymptoten van f gestippeld zijn.
figuur 3: de grafieken van f en g met de gestippelde asymptoten van f en de punten S en R$$, 'inline'),
  ('0d0e711e-5030-4401-bdf7-68f92a256535', '5cbcf919-9680-414f-8aea-71d842e71543', $$cirkel c₁: x² − 4x + y² − 6y = −8; lijn k: y = ½x + 4½; k raakt c₁$$,
   $$wiskunde-b-havo-2021-i-twee-cirkels-en-twee-lijnen-context1.png$$,
   $$De cirkel c₁ wordt gegeven door:
x² − 4x + y² − 6y = −8
De lijn k wordt gegeven door:
y = ½x + 4½
Lijn k raakt cirkel c₁.$$, 'inline'),
  ('3ed5b70e-16e7-4b0d-83c7-4cd01bf35bf1', '5cbcf919-9680-414f-8aea-71d842e71543', $$M middelpunt van c₁; l door M loodrecht op k; S snijpunt van l met de y-as; c₂ cirkel door M met middelpunt S; figuur$$,
   $$wiskunde-b-havo-2021-i-twee-cirkels-en-twee-lijnen-context2.png$$,
   $$Het punt M is het middelpunt van c₁. De lijn l gaat door M en staat loodrecht op k. Het punt S is het snijpunt van l met de y-as. De cirkel c₂ is de cirkel door M met middelpunt S. Zie de figuur.
figuur: de cirkels c₁ en c₂, de lijn k en de lijn l door M en S$$, 'inline'),
  ('11e25f9d-dd49-4046-89b8-df093f0de825', '4e5d3de9-fbad-4a9c-8f79-e60e3345a557', $$f(x) = ¼x² + x + 1; de grafiek van f is een parabool$$,
   $$wiskunde-b-havo-2021-i-oppervlakte-onder-een-grafiek-context1.png$$,
   $$De functie f is gegeven door f(x) = ¼x² + x + 1.
De grafiek van f is een parabool.$$, 'inline'),
  ('2f6ca30d-ec3c-4e45-9249-21e071977f4c', '4e5d3de9-fbad-4a9c-8f79-e60e3345a557', $$lijn m: x = p met p > 0; grijs gebied tussen f, x-as, y-as en m; figuur 1 (p = 1) en figuur 2 (p = 2)$$,
   $$wiskunde-b-havo-2021-i-oppervlakte-onder-een-grafiek-context2.png$$,
   $$De lijn m is de verticale lijn met vergelijking x = p, met p > 0.
We kijken naar het gebied dat aan de bovenkant wordt begrensd door de grafiek van f, aan de onderkant door de x-as, aan de linkerkant door de y-as en aan de rechterkant door lijn m.
In figuren 1 en 2 is dit gebied grijs gemaakt: in figuur 1 voor de situatie p = 1, in figuur 2 voor de situatie p = 2.
figuur 1: het grijze gebied voor p = 1
figuur 2: het grijze gebied voor p = 2$$, 'inline'),
  ('e2e4614a-17ad-4db7-bda1-8e458aed9a5e', '4e5d3de9-fbad-4a9c-8f79-e60e3345a557', $$oppervlakte A = ⅔(½p + 1)³ − ⅔; A = 4⅔ als p = 2; voor een bepaalde p is A = 42$$,
   $$wiskunde-b-havo-2021-i-oppervlakte-onder-een-grafiek-context3.png$$,
   $$De oppervlakte van dit grijze gebied noemen we A. De waarde van A hangt dus af van de keuze van p. Een formule voor A is:
A = ⅔(½p + 1)³ − ⅔
Zo is bijvoorbeeld A = 4⅔ als p = 2 en dus is de oppervlakte van het grijze gebied in figuur 2 gelijk aan 4⅔.
Voor een bepaalde waarde van p is de oppervlakte van het grijze gebied gelijk aan 42.$$, 'inline'),
  ('f3f8ffab-66e6-45bb-b4dd-c439fb9e9fe6', '4e5d3de9-fbad-4a9c-8f79-e60e3345a557', $$benadering voor p = 1: raaklijn l in R(½, 1 9/16), K, M, S(1, 0), vierhoek OSMK; figuur 3; l: y = 1¼x + 15/16$$,
   $$wiskunde-b-havo-2021-i-oppervlakte-onder-een-grafiek-context4.png$$,
   $$Zonder de voorgaande formule te gebruiken kun je toch een goede benadering vinden van de oppervlakte. In de rest van de opgave doen we dit voor het geval p = 1.
De benadering van de oppervlakte van het grijze gebied in figuur 1 gaat als volgt:
– De lijn l is de raaklijn aan de grafiek van f in het punt R(½, 1 9/16).
– K is het snijpunt van lijn l met de y-as.
– M is het snijpunt van lijn l en lijn m.
– S is het punt met coördinaten (1, 0).
– De oppervlakte van vierhoek OSMK is de benadering.
Zie figuur 3, waarin de oppervlakte van vierhoek OSMK grijs is gemaakt.
figuur 3: de grafiek van f, de raaklijn l en de grijze vierhoek OSMK
Een vergelijking van l is y = 1¼x + 15/16.$$, 'inline'),
  ('426cab22-5aca-4d33-a965-68c5e79ce1e6', '4e5d3de9-fbad-4a9c-8f79-e60e3345a557', $$de oppervlakte van vierhoek OSMK wijkt een beetje af van de oppervlakte van het grijze gebied in figuur 1$$,
   $$wiskunde-b-havo-2021-i-oppervlakte-onder-een-grafiek-context5.png$$,
   $$De oppervlakte van de grijs gemaakte vierhoek OSMK in figuur 3 wijkt een beetje af van de oppervlakte van het grijze gebied in figuur 1.$$, 'inline'),
  ('b65c5740-d5b4-4bb8-b73f-a4ca651c444c', '8b7b2115-c080-40bd-aee9-701adc165dd1', $$roei-ergometer; foto$$,
   $$wiskunde-b-havo-2021-i-roeien-context1.png$$,
   $$In sportscholen vind je apparaten waarmee je een roeibeweging simuleert. Zo’n apparaat wordt een roei-ergometer genoemd. Zie de foto.
foto: een roeier op een roei-ergometer$$, 'inline'),
  ('a3ec7519-5b0c-4988-9df4-3a014ec1cec4', '8b7b2115-c080-40bd-aee9-701adc165dd1', $$zijaanzichten van een roeibeweging; figuur 1; zitje beweegt horizontaal, voeten vast$$,
   $$wiskunde-b-havo-2021-i-roeien-context2.png$$,
   $$In figuur 1 zie je een serie zijaanzichten van de beweging van een roeier op een roei-ergometer.
figuur 1: vijf zijaanzichten met de labels moment 1, moment 2, moment 3, moment 4 en moment 3 (⚠️ CONTROLEREN: het laatste label is in de bron ''moment 3'', vermoedelijk moment 5)
Doordat het voetenbord vast zit, blijven de voeten vast op één punt. Wanneer de roeier de benen strekt en weer buigt, beweegt het zitje horizontaal van voor naar achter en weer terug. De roeibeweging begint op moment 1, waarna de roeier zijn benen strekt (momenten 2 en 3). Daarna worden de benen weer gebogen (momenten 4 en 5).$$, 'inline'),
  ('61de2162-154e-46c5-9a24-398dff3ab8d3', '8b7b2115-c080-40bd-aee9-701adc165dd1', $$model van een roeier op de momenten 1 en 3; V voet, K knie, H heup; figuur 2 (ook op de uitwerkbijlage)$$,
   $$wiskunde-b-havo-2021-i-roeien-context3.png$$,
   $$In figuur 2 zie je een model van een roeier op de momenten 1 en 3. Deze figuur staat ook op de uitwerkbijlage. Het punt V is de voet, K is de knie en H is de heup (die in dit model samenvalt met het zitje).
figuur 2: model van de roeier op moment 1 en moment 3 met de punten H₁, K₁, H₃, K₃, V, A₁ en A₃$$, 'inline'),
  ('84b4ea35-6bf2-4e79-b726-cca775dd244d', '8b7b2115-c080-40bd-aee9-701adc165dd1', $$bovenbeen 48 cm, onderbeen 42 cm, hoogteverschil heup-voet 15 cm, zitje schuift 45 cm, hoek op moment 1 is 60°; A punt recht onder de heup; H1V ≈ 45,3 cm$$,
   $$wiskunde-b-havo-2021-i-roeien-context4.png$$,
   $$In dit model geldt:
– De lengte van het bovenbeen is 48 cm.
– De lengte van het onderbeen is 42 cm.
– Het hoogteverschil tussen heup en voet is 15 cm.
– Tussen de momenten 1 en 3 schuift het zitje 45 cm naar achteren.
– De hoek tussen bovenbeen en onderbeen op moment 1 is 60°.
– A is het punt recht onder de heup, op dezelfde hoogte als de voet.
– Met A₁ wordt de positie van A op moment 1 bedoeld enzovoorts.
Op moment 1 is de afstand tussen de heup en de voet (H₁V) ongeveer 45,3 cm. Deze afstand kan exact berekend worden.$$, 'inline'),
  ('411843c5-479f-4c38-9a9c-cc961eff6a5c', '8b7b2115-c080-40bd-aee9-701adc165dd1', $$ga uit van H1V = 45,3; hoek H3K3V bijna 180°; gebruik de driehoeken A1VH1 en A3VH3$$,
   $$wiskunde-b-havo-2021-i-roeien-context5.png$$,
   $$Ga bij het volgende onderdeel uit van H₁V = 45,3.
Op moment 3 is het been bijna gestrekt, dus hoek H₃K₃V is bijna 180°.
Om deze hoek te berekenen, is het handig om gebruik te maken van de driehoeken A₁VH₁ en A₃VH₃.$$, 'inline'),
  ('611a9919-1cb2-43be-8e29-0002f759bcad', '8b7b2115-c080-40bd-aee9-701adc165dd1', $$uitwerkbijlage bij vraag 10: figuur 2$$,
   $$wiskunde-b-havo-2021-i-roeien-context6.png$$,
   $$uitwerkbijlage bij vraag 10: figuur 2, model van de roeier op moment 1 en moment 3$$, 'uitwerkbijlage'),
  ('01340b49-6a7d-4a68-b8cd-30d0e9e04186', '8b7b2115-c080-40bd-aee9-701adc165dd1', $$uitwerkbijlage bij vraag 11: figuur 2$$,
   $$wiskunde-b-havo-2021-i-roeien-context7.png$$,
   $$uitwerkbijlage bij vraag 11: figuur 2, model van de roeier op moment 1 en moment 3$$, 'uitwerkbijlage'),
  ('453e7b9a-a718-4e27-938b-3fed92e4528a', '37421b10-c1f3-4923-87f1-f6cdb6c06d01', $$f(x) = 3sin(¼πx); A eerste snijpunt met de positieve x-as; B derde top rechts van de y-as; lijn k door A en B maakt hoek α met de x-as; figuur 1$$,
   $$wiskunde-b-havo-2021-i-een-sinusoide-en-nog-een-sinusoide-context1.png$$,
   $$De functie f wordt gegeven door f(x) = 3sin(¼πx).
Het punt A is het eerste snijpunt van de grafiek van f met de positieve x-as. Het punt B is de derde top rechts van de y-as.
De lijn k gaat door A en B. In figuur 1 is de hoek α aangegeven die lijn k met de x-as maakt.
figuur 1: de grafiek van f en de lijn k door A en B met de hoek α$$, 'inline'),
  ('cb9910d4-1f9e-4961-9f20-9b958109d41f', '37421b10-c1f3-4923-87f1-f6cdb6c06d01', $$lijn y = 1½; K eerste en L vierde snijpunt met f; gestippelde sinusoïde met toppen in K en L die y = −1 raakt; figuur 2; g(x) = a · cos(b(x − c)) + d$$,
   $$wiskunde-b-havo-2021-i-een-sinusoide-en-nog-een-sinusoide-context2.png$$,
   $$In figuur 2 is de grafiek van f getekend en ook de lijn met vergelijking y = 1½. Deze lijn heeft oneindig veel snijpunten met de grafiek van f. Het eerste snijpunt rechts van de y-as is K, het vierde is L.
In figuur 2 is met een stippellijn nog een sinusoïde weergegeven. Voor deze sinusoïde geldt:
– De eerste top rechts van de y-as valt samen met K.
– De derde top rechts van de y-as valt samen met L.
– De sinusoïde raakt de lijn met vergelijking y = −1.
figuur 2: de grafiek van f, de lijnen y = 1½ en y = −1 en de gestippelde sinusoïde door K en L
De functie g die bij de gestippelde grafiek hoort, heeft een functievoorschrift van de volgende vorm:
g(x) = a · cos(b(x − c)) + d
Hierin zijn a, b, c en d getallen$$, 'inline'),
  ('7b260947-18e4-4036-8194-a8e8a5f1f98f', 'cb307527-7833-4f28-86bb-9ac96d2c6857', $$f(x) = 3√x − 2x + 1; T top van de grafiek van f; figuur 1$$,
   $$wiskunde-b-havo-2021-i-driehoek-met-maximale-oppervlakte-context1.png$$,
   $$De functie f wordt gegeven door f(x) = 3√x − 2x + 1.
Het punt T is de top van de grafiek van f. Zie figuur 1.
figuur 1: de grafiek van f met de top T$$, 'inline'),
  ('1934cded-1d9c-439d-92d5-0de21acabdaa', 'cb307527-7833-4f28-86bb-9ac96d2c6857', $$P op de grafiek van f boven de x-as; A op de x-as met dezelfde x-coördinaat als P; driehoek OAP; figuur 2 en figuur 3$$,
   $$wiskunde-b-havo-2021-i-driehoek-met-maximale-oppervlakte-context2.png$$,
   $$Op het deel van de grafiek van f dat boven de x-as ligt, wordt een punt P gekozen. Het punt A ligt op de x-as en heeft dezelfde x-coördinaat als P.
In figuur 2 en figuur 3 is de situatie voor twee posities van P geschetst. In figuur 3 is de oppervlakte van driehoek OAP groter dan in figuur 2.
figuur 2 en figuur 3: de grafiek van f met de driehoek OAP voor twee posities van P$$, 'inline'),
  ('5bdab53b-8762-44b2-933e-587d52ef65e3', 'cb307527-7833-4f28-86bb-9ac96d2c6857', $$oppervlakte van driehoek OAP maximaal; oppervlakte uitdrukken in x = OA$$,
   $$wiskunde-b-havo-2021-i-driehoek-met-maximale-oppervlakte-context3.png$$,
   $$Er is een positie van P op de grafiek van f zo dat de oppervlakte van driehoek OAP maximaal is. Deze positie van P kun je vinden door de oppervlakte van driehoek OAP in x uit te drukken, waarbij x de lengte van zijde OA is.$$, 'inline'),
  ('3b4f0314-f7d3-4126-9ee5-752c19fffd43', 'f0c0c79b-37d6-4358-b363-98abd55abd58', $$inleiding: prestaties van langeafstandslopers nemen na ongeveer 30 jaar af; twee modellen$$,
   $$wiskunde-b-havo-2021-i-de-invloed-van-leeftijd-op-hardloopprestaties-context1.png$$,
   $$Gemiddeld leveren langeafstandslopers de beste prestaties op een leeftijd van ongeveer 30 jaar. Daarna nemen de prestaties met de jaren af. Er bestaan meerdere modellen om de prestaties van langeafstandslopers van verschillende leeftijden met elkaar te vergelijken. In deze opgave komen twee van zulke modellen aan bod.$$, 'inline'),
  ('376db646-a305-43f1-a95d-e23a3ed583da', 'f0c0c79b-37d6-4358-b363-98abd55abd58', $$model 1: gemiddelde snelheid neemt tussen 35 en 55 jaar met 0,8% per levensjaar af; halve marathon 21,0975 km; Aart Stigter 1993 (36 jaar) 19,5 km/uur, 2005 in 1 uur, 10 minuten en 4 seconden$$,
   $$wiskunde-b-havo-2021-i-de-invloed-van-leeftijd-op-hardloopprestaties-context2.png$$,
   $$Model 1 Dit model gaat ervan uit dat tussen 35 en 55 jaar de gemiddelde snelheid van langeafstandslopers bij wedstrijden met 0,8% per levensjaar afneemt.
De halve marathon is een hardloopwedstrijd over een afstand van 21,0975 km. De Nederlandse hardloper Aart Stigter heeft meerdere keren aan de halve marathon van Egmond deelgenomen. In 1993 liep hij op 36-jarige leeftijd deze halve marathon met een gemiddelde snelheid van 19,5 km per uur. Precies 12 jaar later, in 2005, liep hij dezelfde halve marathon in een tijd van 1 uur, 10 minuten en 4 seconden.
Uitgaande van zijn gemiddelde snelheid in 1993 en een afname van die gemiddelde snelheid met 0,8% per levensjaar, heeft Aart Stigter in 2005 sneller gelopen dan model 1 voorspelt.$$, 'inline'),
  ('91e6d8a8-fa98-4539-b7d2-d62c5f32cf93', 'f0c0c79b-37d6-4358-b363-98abd55abd58', $$model 2: correctiegetallen voor de tijd (WMA); tabel: 36 jaar 0,9920, 49 jaar 0,9039; correctiegetallen nemen exponentieel af met de leeftijd$$,
   $$wiskunde-b-havo-2021-i-de-invloed-van-leeftijd-op-hardloopprestaties-context3.png$$,
   $$Model 2
Dit model maakt gebruik van correctiegetallen voor de tijd.
De World Master Athletics-bond (WMA) heeft tabellen uitgegeven met correctiegetallen om prestaties van hardlopers van verschillende leeftijden met elkaar te kunnen vergelijken. Met deze correctiegetallen kun je de tijd van elke hardloper omrekenen naar een tijd die hoort bij een 30-jarige met een gelijkwaardige prestatie.
In de tabel zie je de correctiegetallen voor 36-jarigen en 49-jarigen op de halve marathon. Door de tijd van een 36-jarige hardloper met 0,9920 te vermenigvuldigen krijg je de tijd die hoort bij een 30-jarige hardloper met een gelijkwaardige prestatie. Neem aan dat de correctiegetallen voor de leeftijden tussen 36 en 49 jaar bij benadering exponentieel afnemen met de leeftijd.
tabel: leeftijd 36 – correctiegetal t.o.v. 30-jarige 0,9920; leeftijd 49 – correctiegetal 0,9039$$, 'inline'),
  ('876901c5-ab36-4886-83a0-2b94550c7393', 'f0c0c79b-37d6-4358-b363-98abd55abd58', $$NK halve marathon 2019: Marcel Laros (47 jaar) 4279 s; Wynfrith Meijwes (36 jaar) 4130 s$$,
   $$wiskunde-b-havo-2021-i-de-invloed-van-leeftijd-op-hardloopprestaties-context4.png$$,
   $$Bij de NK halve marathon 2019 was de 47-jarige Marcel Laros met een tijd van 4279 seconden de snelste in de categorie 45-49 jaar. Bij diezelfde halve marathon was de 36-jarige Wynfrith Meijwes de snelste in de categorie 35-39 met een tijd van 4130 seconden.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('abb6d981-3836-474c-9fed-6ac734b9da8d', 'e3fa6b7d-ad8d-4f81-a97c-ffe0422ad106', 1,
   '[{"domain": "Toegepaste analyse", "subdomain": "Bepaling afgeleide functies"}, {"domain": "Toegepaste analyse", "subdomain": "Toepassing afgeleide functies"}]'::jsonb,
   '["quotiëntregel", "kettingregel", "afgeleide", "helling in een punt", "gebroken functie", "exact berekenen"]'::jsonb,
   $$Met de afgeleide van een gebroken functie exact de helling van de grafiek in een punt berekenen.$$,
   $$wiskunde-b-havo-2021-i-gebroken-functie-en-wortelfunctie-vraag1.png$$, $$4p 1 Bereken exact de helling van de grafiek van f in O$$, array['364a90b8-11a1-47e1-baad-cea033dad1cc']::uuid[]),
  ('c978cdcb-3c23-4949-8c5c-e36fe4a37ce5', 'e3fa6b7d-ad8d-4f81-a97c-ffe0422ad106', 2,
   '[{"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Vergelijkingen en ongelijkheden"}]'::jsonb,
